import type { Metadata } from "next";
import { prisma } from "@/lib/prisma";
import { ContentDraftActions } from "@/components/admin/content-draft-actions";

export const metadata: Metadata = { title: "Content | HEIDIZ Admin" };

const TYPE_LABELS: Record<string, string> = {
  SOCIAL_POST: "Social Post",
  PROMO_EMAIL: "Promo Email",
  BLOG_IDEA: "Blog Idea",
};

// Weekly AI-drafted marketing copy, generated by /api/cron/content-drafts
// (see src/lib/ai-agents.ts) from the real catalog. Reviewed here, never
// published from here: there's no Instagram/Facebook/campaign-sender
// integration behind this, deliberately, so every action on this page is
// either "mark reviewed" or "copy the text out". See the ContentDraft
// comment in prisma/schema.prisma for why.
export default async function AdminContentPage() {
  const drafts = await prisma.contentDraft.findMany({ orderBy: { createdAt: "desc" }, take: 60 });
  const needsReview = drafts.filter((d) => d.status === "DRAFT").length;

  return (
    <div className="p-8 md:p-10">
      <h1 className="font-display text-2xl text-brand-black">Content Drafts</h1>
      <p className="mt-1 text-sm text-charcoal/70">
        {drafts.length} draft{drafts.length === 1 ? "" : "s"} total &middot; {needsReview} need
        {needsReview === 1 ? "s" : ""} review
      </p>
      <p className="mt-3 max-w-2xl text-xs text-charcoal/70">
        Generated weekly from real catalog data (best sellers, new arrivals, live collections).
        Nothing here is posted or sent automatically, review and copy out what you want to use.
      </p>

      <div className="mt-8 flex flex-col gap-4">
        {drafts.map((draft) => (
          <div key={draft.id} className="rounded-[4px] border border-brand-black/10 bg-white p-6">
            <div className="flex flex-wrap items-start justify-between gap-4">
              <div>
                <span className="text-xs uppercase tracking-wide text-burnt-orange">
                  {TYPE_LABELS[draft.type] ?? draft.type}
                </span>
                <h2 className="mt-1 font-display text-lg text-brand-black">{draft.title}</h2>
              </div>
              <ContentDraftActions id={draft.id} body={draft.body} currentStatus={draft.status} />
            </div>
            <p className="mt-4 whitespace-pre-wrap text-sm leading-relaxed text-charcoal/80">{draft.body}</p>
            <p className="mt-3 text-xs text-charcoal/70">
              {new Date(draft.createdAt).toLocaleDateString("en-NG", { day: "numeric", month: "short", year: "numeric" })}
            </p>
          </div>
        ))}
        {drafts.length === 0 && (
          <p className="py-10 text-center text-sm text-charcoal/70">
            No drafts yet. The first batch generates on the next weekly run.
          </p>
        )}
      </div>
    </div>
  );
}
